CREATE TABLE courses (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE subjects (id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE RESTRICT, semester INTEGER NOT NULL CHECK(semester>=1), subject_code TEXT NOT NULL COLLATE NOCASE, name TEXT NOT NULL, UNIQUE(course_id,semester,subject_code));
CREATE TABLE students (id INTEGER PRIMARY KEY, enrollment_no TEXT NOT NULL UNIQUE COLLATE NOCASE, full_name TEXT NOT NULL, email TEXT, phone TEXT, course_id INTEGER REFERENCES courses(id), semester INTEGER CHECK(semester IS NULL OR semester>=1), batch TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','graduated','withdrawn')));
CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, role TEXT NOT NULL CHECK(role IN ('admin','student')), password_hash TEXT NOT NULL, recovery_key_hash TEXT, student_id INTEGER UNIQUE REFERENCES students(id), is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), failed_attempts INTEGER NOT NULL DEFAULT 0, locked_until TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((role='student' AND student_id IS NOT NULL) OR (role='admin' AND student_id IS NULL)));
CREATE TABLE audit_logs (id INTEGER PRIMARY KEY, actor_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, old_values TEXT, new_values TEXT, details TEXT);
CREATE TABLE import_logs (id INTEGER PRIMARY KEY, source_name TEXT NOT NULL, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, status TEXT NOT NULL CHECK(status IN ('started','succeeded','failed','partial')), rows_seen INTEGER NOT NULL DEFAULT 0, rows_imported INTEGER NOT NULL DEFAULT 0, rows_rejected INTEGER NOT NULL DEFAULT 0, message TEXT);
CREATE INDEX idx_students_course ON students(course_id);
CREATE INDEX idx_audit_logs_time ON audit_logs(occurred_at);
